#include <stdio.h>

int main() {
    int sum = 0, i = 1;
    // sum 记录已处理整数的总和。i 指向下一项，最大累加到 100。
    while (i <= 100) {
        sum += i;
        i++;
    }
    printf("%d\n", sum);
    return 0;
}
